    /// The BloodContainer of the struct in `slot` (its SerialisableDistributions and OnBeforeSerialise / OnAfterDeserialise).
    pub(super) fn slot_owner(slot: Slot) -> Option<Owner> {
        match slot {
            Slot::Flasks(i) => Some(Owner::Flask(i)),
            Slot::Syringes(i) => Some(Owner::Syringe(i)),
            Slot::Valves(i) => Some(Owner::Valve(i)),
            Slot::LiquidDuplicators(i) => Some(Owner::LiquidDuplicator(i)),
            Slot::LiquidPumps(i) => Some(Owner::LiquidPump(i)),
            Slot::Centrifuges(i) => Some(Owner::Centrifuge(i)),
            Slot::Liquidentifiers(i) => Some(Owner::Liquidentifier(i)),
            Slot::LiquidCanisters(i) => Some(Owner::LiquidCanister(i)),
            Slot::LiquidFilters(i) => Some(Owner::LiquidFilter(i)),
            Slot::BloodTanks(i) => Some(Owner::BloodTank(i)),
            Slot::LiquidOutlets(i) => Some(Owner::LiquidOutlet(i)),
            Slot::ReactorConduits(i) => Some(Owner::ReactorConduit(i)),
            _ => None,
        }
    }
